head.script:
scwin.fn_GetPar, scwin.fn_SetPar, scwin.fr_SecuGrpId;
scwin.gBzProcsNo;
scwin.gAcptNo;
scwin.gListProcsStatCd;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
    try {
        const vCurDate = $c.ut.cGetToday("yyyymmdd");
        edt_SDate.setValue(vCurDate);
        $c.cm.PanelToGroupBox(panel_Top);
        $c.cm.setColumnProp(grd_List_1, "REGULAR_CD", "Show", false);
        $c.cm.setColumnProp(grd_List_1, "NONSCHE_CD", "Show", false);
        $c.cm.setColumnProp(grd_List_1, "SECT_TP_CD", "Show", false);
        $c.cm.setColumnProp(grd_List_1, "ISUR_CD", "Show", false);
        $c.cm.setColumnProp(grd_List_2, "REGULAR_CD", "Show", false);
        $c.cm.setColumnProp(grd_List_2, "NONSCHE_CD", "Show", false);
        $c.cm.setColumnProp(grd_List_2, "SECT_TP_CD", "Show", false);
        $c.cm.setColumnProp(grd_List_2, "ISUR_CD", "Show", false);

        // fn_list_sync() ;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05970.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name MaxTab_01_OnSelChanged
 * @description Max Tab 01 On Sel Changed 처리
 * @param {*} nIndex nIndex
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.MaxTab_01_OnSelChanged = async function(nIndex) {
    try {
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05970.MaxTab_01_OnSelChanged" });
    }
};

/**
 * @method
 * @name grd_List_1_OnDblClick
 * @description grd_List_1 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_List_1_OnDblClick = async function(row, colid) {
    try {
        await scwin.openDetail(row);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05970.grd_List_1_OnDblClick" });
    }
};

/**
 * @method
 * @name btn_SDate_onclick
 * @description btn_SDate 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_SDate_onclick = function() {
    try {
        popUpCalendar2(edt_SDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05970.btn_SDate_onclick" });
    }
};

/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05970.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05970.btn_Close_onclick" });
    }
};

/**
 * @method
 * @name dts_List_1_OnLoadCompleted
 * @description dts_List_1 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_1_OnLoadCompleted = function(rowcount) {
};

/**
 * @method
 * @name dts_List_1_OnLoadError
 * @description dts_List_1 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_1_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_List_1);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05970.dts_List_1_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_List_2_OnLoadCompleted
 * @description dts_List_2 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_2_OnLoadCompleted = function(rowcount) {
};

/**
 * @method
 * @name dts_List_2_OnLoadError
 * @description dts_List_2 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_2_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_List_2);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05970.dts_List_2_OnLoadError" });
    }
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function() {
    try {
        $c.stf.doLogSave("ULDSTF05970.xml", SCREN_PROCS_TP_CD_07);
        if (MaxTab_01.getSelectedTabIndex() === 1) {
            $c.data.downloadGridViewExcel(grd_List_1, {fileName: "소속부변경 시뮬레이션", type: "8"});
        } else {
            $c.data.downloadGridViewExcel(grd_List_2, {fileName: "소속부변경 정기심사이력", type: "8"});
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05970.btn_Excel_onclick" });
    }
};

/**
 * @method
 * @name txb_ISUR_CD_onblur
 * @description txb_ISUR_CD 포커스 이탈 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_ISUR_CD_onblur = function() {
    try {
        if (txb_ISUR_CD.getValue() === "") {
            txb_COM_NM.setValue("");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05970.txb_ISUR_CD_onblur" });
    }
};

/**
 * @method
 * @name img_COM_NM_onclick
 * @description img_COM_NM 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_COM_NM_onclick = function() {
    try {
        scwin.fn_GetPar = scwin.getParIsur;
        scwin.fn_SetPar = scwin.setParIsur;
        $c.lc.fn_PopFindCorpChrg(scwin.fr_SecuGrpId);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05970.img_COM_NM_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name listSync
 * @description list Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync = async function() {
    if (edt_SDate.getValue() === "") {
        await $c.win.alert("조회일자를 입력해 주십시오.");
        edt_SDate.focus();
    }
    const vmm = edt_SDate.getValue().substring(4, 6);
    if (MaxTab_01.getSelectedTabIndex() === 1) {
        if (vmm === "01" || vmm === "02" || vmm === "03" || vmm === "04") {
            $c.cm.setColumnProp(grd_List_1, "RECENT_01", "name", (Number(edt_SDate.getValue().substring(0, 4)) - 2) + "년(최근)");
            $c.cm.setColumnProp(grd_List_1, "RECENT_02", "name", (Number(edt_SDate.getValue().substring(0, 4)) - 3) + "년(최근-1년)");
            $c.cm.setColumnProp(grd_List_1, "RECENT_03", "name", (Number(edt_SDate.getValue().substring(0, 4)) - 4) + "년(최근-2년)");
        } else {
            $c.cm.setColumnProp(grd_List_1, "RECENT_01", "name", (Number(edt_SDate.getValue().substring(0, 4)) - 1) + "년(최근)");
            $c.cm.setColumnProp(grd_List_1, "RECENT_02", "name", (Number(edt_SDate.getValue().substring(0, 4)) - 2) + "년(최근-1년)");
            $c.cm.setColumnProp(grd_List_1, "RECENT_03", "name", (Number(edt_SDate.getValue().substring(0, 4)) - 3) + "년(최근-2년)");
        }
        url += "?SCREN_ID=" + "ULDSTF05970.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        url += "&method=listSectSimulation&inputMessageId=SECT_SIMULATION_INOUT";
        url += "&LIST_DD=" + edt_SDate.getValue();
        url += "&ISUR_CD=" + txb_ISUR_CD.getValue();
        const sbmOptions = {
            id : "sbm_dts_List_1",
            action : "/SectionTypeChange.do",
            ref : "",
            target : "dts_List_1=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    } else {
        if (vmm === "01" || vmm === "02" || vmm === "03" || vmm === "04") {
            $c.cm.setColumnProp(grd_List_2, "RECENT_01", "name", (Number(edt_SDate.getValue().substring(0, 4)) - 2) + "년(최근)");
            $c.cm.setColumnProp(grd_List_2, "RECENT_02", "name", (Number(edt_SDate.getValue().substring(0, 4)) - 3) + "년(최근-1년)");
            $c.cm.setColumnProp(grd_List_2, "RECENT_03", "name", (Number(edt_SDate.getValue().substring(0, 4)) - 4) + "년(최근-2년)");
        } else {
            $c.cm.setColumnProp(grd_List_2, "RECENT_01", "name", (Number(edt_SDate.getValue().substring(0, 4)) - 1) + "년(최근)");
            $c.cm.setColumnProp(grd_List_2, "RECENT_02", "name", (Number(edt_SDate.getValue().substring(0, 4)) - 2) + "년(최근-1년)");
            $c.cm.setColumnProp(grd_List_2, "RECENT_03", "name", (Number(edt_SDate.getValue().substring(0, 4)) - 3) + "년(최근-2년)");
        }
        url += "?SCREN_ID=" + "ULDSTF05970.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        url += "&method=listSectSimulationHist&inputMessageId=SECT_SIMULATION_INOUT";
        url += "&LIST_DD=" + edt_SDate.getValue();
        url += "&ISUR_CD=" + txb_ISUR_CD.getValue();
        const sbmOptions = {
            id : "sbm_dts_List_2",
            action : "/SectionTypeChange.do",
            ref : "",
            target : "dts_List_2=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    }
};

/**
 * @method
 * @name popupCallback
 * @description browserPopup 팝업의 callback 함수. 부모창에서 팝업 결과 값을 처리한다.
 * @param {*} arg 팝업에서 전달받은 값
 * @returns {void}
 * @hidden N
 */
scwin.popupCallback = function (arg) {
    // TO-DO : arg 값 확인 후 업무 로직 추가
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name getParIsur
 * @description 넘길 인수를 지정하는 펑션
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParIsur = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = txb_ISUR_CD.getValue(); // 발행기관코드값
    arrPar[1] = txb_COM_NM.getValue(); // 발행기관명
    arrPar[2] = scwin.fr_SecuGrpId; // 명칭값을 포함할 컨트롤
    arrPar[3] = "9"; // 회사코드팝업 전체데이터
    return arrPar.length;
};

/**
 * @method
 * @name setParIsur
 * @description set Par Isur 처리
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.setParIsur = function(arrPar) {
    const dbClickYn = arrPar[0].DBCLICKYN;
    if (dbClickYn === "Y") {
        txb_ISUR_CD.setValue(arrPar[0].ISUR_CD);
        txb_COM_NM.setValue(arrPar[0].COM_NM);
    }
};

/**
 * @method
 * @name openDetail
 * @description open Detail 처리
 * @param {Number} row 행 인덱스
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.openDetail = async function(row) {
    const options = {
        id: "ULDSTF05971",
        title: "소속부변경",
        type: "browserPopup",
        width: "720px",
        height: "420px",
        callbackFn: "scwin.popupCallback"
    };

    $c.win.openPopup("/lstproc/ULDSTF05971.gfm", options);
};
